import{_ as a,c as t,o as r,ag as l}from"./chunks/framework.D7gJy-HQ.js";const b=JSON.parse('{"title":"IM（Electron）","description":"","frontmatter":{},"headers":[],"relativePath":"web/IM.md","filePath":"web/IM.md"}'),i={name:"web/IM.md"};function o(n,e,h,s,c,d){return r(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="im-electron" tabindex="-1">IM（Electron） <a class="header-anchor" href="#im-electron" aria-label="Permalink to &quot;IM（Electron）&quot;">​</a></h1><h2 id="websocket" tabindex="-1">WebSocket <a class="header-anchor" href="#websocket" aria-label="Permalink to &quot;WebSocket&quot;">​</a></h2><h3 id="web-worker-心跳机制" tabindex="-1">Web Worker 心跳机制 <a class="header-anchor" href="#web-worker-心跳机制" aria-label="Permalink to &quot;Web Worker 心跳机制&quot;">​</a></h3><p>使用 Web Worker 处理心跳定时器，解决 Electron 窗口不聚焦或隐藏时定时器不准确的问题，确保 WebSocket 心跳包稳定发送。</p><h3 id="指数退避重连算法" tabindex="-1">指数退避重连算法 <a class="header-anchor" href="#指数退避重连算法" aria-label="Permalink to &quot;指数退避重连算法&quot;">​</a></h3><ul><li>初始重连间隔：10 秒</li><li><strong>窗口聚焦</strong>：5~10 秒区间内随机重连</li><li><strong>窗口失焦</strong>：10~15 秒区间内随机重连</li></ul><h2 id="sqlite" tabindex="-1">SQLite <a class="header-anchor" href="#sqlite" aria-label="Permalink to &quot;SQLite&quot;">​</a></h2><h2 id="sqlite数据库操作使用typeorm" tabindex="-1">SQLite数据库操作使用TYPEORM <a class="header-anchor" href="#sqlite数据库操作使用typeorm" aria-label="Permalink to &quot;SQLite数据库操作使用TYPEORM&quot;">​</a></h2><h3 id="路由式数据访问" tabindex="-1">路由式数据访问 <a class="header-anchor" href="#路由式数据访问" aria-label="Permalink to &quot;路由式数据访问&quot;">​</a></h3><p>在主线程通过路由形式注册数据请求方法，保持与常规接口请求一致的调用方式。</p><h3 id="并发控制" tabindex="-1">并发控制 <a class="header-anchor" href="#并发控制" aria-label="Permalink to &quot;并发控制&quot;">​</a></h3><p>使用 RxJS 队列限制 SQLite 操作并发，保障数据库可用性。</p><h3 id="数据一致性保障" tabindex="-1">数据一致性保障 <a class="header-anchor" href="#数据一致性保障" aria-label="Permalink to &quot;数据一致性保障&quot;">​</a></h3><p>在接口请求层使用 RxJS 适配器：</p><ul><li>检查 SQLite 数据连续性与准确性</li><li>极端情况下（数据库不可用）自动降级为服务端接口同步</li><li>RAGMA busy_timeout=5000 数据库超时，自动降级为服务端接口同步</li></ul><h3 id="大量数据写入" tabindex="-1">大量数据写入 <a class="header-anchor" href="#大量数据写入" aria-label="Permalink to &quot;大量数据写入&quot;">​</a></h3><p>在处理大量数据写入时，采用分批处理和异步写入策略，避免阻塞主线程，确保界面流畅。</p><ul><li>进行数据切片，每次处理固定数量的数据项</li><li>使用异步API进行数据库写入，避免阻塞主线程</li></ul><h2 id="页面响应优先" tabindex="-1">页面响应优先 <a class="header-anchor" href="#页面响应优先" aria-label="Permalink to &quot;页面响应优先&quot;">​</a></h2><p>在用户登录的过程中，优先保证页面的响应速度和用户体验。</p><ul><li>在登录成功后需要通过接口获取最新的回话列表和最新的消息，这个时候优先取本地数据库的数据，然后接口请求完毕后再进行更新</li></ul>',21)])])}const q=a(i,[["render",o]]);export{b as __pageData,q as default};
